SELECT count(*)=5 AND bool_and(encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')=e.expected_hash) AS present FROM(VALUES ('petro_private','cancel_service_order_core','37996868ed1abee46b5dd3233174b3ebc2f3aec538ddafe4fd61f1294ab73633'),('public','petro_confirm_service_order','f119d3371ba4b819d9e60a0b603df85f4f4d45fe70d2feafbd1092f31fe9ade8'),('public','petro_deliver_service_order','0931468baab19bd97a39d4a386929172c726e93a1018ad8bf644ca40a17c5ca3'),('public','petro_start_service_order','0b90454f8583b448aa047510c7510438076de753f3e21db974a54f60f8531d46'),('public','petro_worker_reserve_service_order','7cbc6c7252bce095b9530b319e7f4374724118676240fed2912cbfb24246cb17')) e(schema_name,function_name,expected_hash) JOIN pg_namespace n ON n.nspname=e.schema_name JOIN pg_proc p ON p.pronamespace=n.oid AND p.proname=e.function_name;
